#!/usr/bin/env python3
"""Create a responsive offline dashboard with scenario playback and optional live-server controls."""
from __future__ import annotations
import json
import pathlib


def build_dashboard(records: list[dict], output: pathlib.Path, profile: dict, autonomous_demo: dict | None = None) -> None:
    safe_json = json.dumps(records, separators=(",", ":")).replace("</", "<\\/")
    safe_auto = json.dumps(autonomous_demo or {}, separators=(",", ":")).replace("</", "<\\/")
    profile_name = profile.get("profile_name", "AIBARS profile")
    page = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AIBARS Advanced Operations Dashboard</title>
<style>
:root{color-scheme:dark;--bg:#0b1220;--panel:#121d30;--panel2:#17253b;--line:#283a55;--text:#e8eff8;--muted:#94a8c2;--blue:#6db5ff;--green:#57d6a0;--amber:#f4c36b;--red:#ff7885;--shadow:0 18px 50px #0005}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#162945,#0b1220 62%);color:var(--text);font:14px/1.5 Inter,Segoe UI,system-ui,sans-serif}main{max-width:1480px;margin:auto;padding:28px 24px 70px}.top{display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap}.eyebrow{letter-spacing:.16em;text-transform:uppercase;color:var(--blue);font-size:11px;font-weight:700}h1{margin:5px 0;font-size:clamp(28px,4vw,42px);letter-spacing:-.04em}.sub{color:var(--muted);margin:0}.tag{border:1px solid #355275;background:#10213a;border-radius:999px;padding:7px 12px;color:#b7d9ff;font-size:12px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.riskrow{display:grid;grid-template-columns:105px 1fr 42px;gap:12px;align-items:center;margin:11px 0}.risktrack{height:10px;background:#23334a;border-radius:20px;overflow:hidden}.riskfill{height:100%;border-radius:20px}.risk-low{background:#57d6a0}.risk-moderate{background:#f4c36b}.risk-high{background:#ff9b61}.risk-critical{background:#ff7885}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:26px 0}.metric,.panel{background:linear-gradient(145deg,#15243a,#101a2b);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.metric{padding:18px}.metric .label{color:var(--muted);font-size:12px}.metric .value{font-size:29px;font-weight:750;margin-top:5px;letter-spacing:-.03em}.metric .hint{font-size:11px;color:var(--muted)}.cols{display:grid;grid-template-columns:1.08fr .92fr;gap:16px}.panel{padding:20px;margin-bottom:16px}.panel h2{margin:0 0 14px;font-size:17px}.muted{color:var(--muted)}.scenario-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.scenario{border:1px solid var(--line);background:#101b2c;color:var(--text);border-radius:11px;padding:12px;text-align:left;cursor:pointer;transition:.15s}.scenario:hover,.scenario.active{border-color:var(--blue);background:#172d49}.scenario b{display:block;font-size:13px}.scenario small{color:var(--muted)}button{font:inherit}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}.btn{border:1px solid #385575;background:#173252;color:#d9ecff;border-radius:9px;padding:9px 12px;cursor:pointer}.btn:hover{background:#20446d}.btn.ghost{background:transparent}.status{border-radius:999px;padding:4px 8px;font-size:11px;font-weight:700;display:inline-block}.good{background:#123b32;color:var(--green)}.warn{background:#49371c;color:var(--amber)}.bad{background:#4b202c;color:var(--red)}.kv{display:grid;grid-template-columns:140px 1fr;gap:8px 14px}.kv div:nth-child(odd){color:var(--muted)}.bar{height:9px;background:#23334a;border-radius:20px;overflow:hidden}.bar span{display:block;height:100%;background:linear-gradient(90deg,#50c6a0,#6db5ff)}.eventlist{max-height:420px;overflow:auto;padding:0;margin:0;list-style:none}.eventlist li{border-bottom:1px solid #26364e;padding:10px 0}.eventlist li:last-child{border:0}.tick{color:var(--blue);font-variant-numeric:tabular-nums;font-size:11px}.eventtitle{font-weight:650}.eventdetail{color:var(--muted);font-size:12px;overflow-wrap:anywhere}.evidence-list{margin:8px 0 14px;padding-left:20px}.evidence-list li{margin:7px 0;color:var(--muted)}.evidence-list b{color:var(--text)}.wide{grid-column:1/-1}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:680px}th,td{text-align:left;padding:10px;border-bottom:1px solid #283a55}th{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.foot{margin-top:24px;color:var(--muted);font-size:12px}.notice{padding:11px 13px;border:1px solid #42516a;background:#121f32;border-radius:10px;color:#b5c4d7;font-size:12px;margin-top:12px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.risknum{font-size:35px;font-weight:750}.search{background:#0d1828;border:1px solid var(--line);border-radius:9px;padding:9px;color:var(--text);width:100%}.hide{display:none}@media(max-width:960px){.grid{grid-template-columns:repeat(2,1fr)}.cols{grid-template-columns:1fr}}@media(max-width:560px){main{padding:18px 12px 40px}.grid{grid-template-columns:1fr 1fr}.scenario-list{grid-template-columns:1fr}.kv{grid-template-columns:110px 1fr}.two{grid-template-columns:1fr}}
</style></head><body><main>
<header class="top"><div><div class="eyebrow">Embedded resilience platform · release v2.3.2</div><h1>AIBARS Operations Center</h1><p class="sub">Artificial Intelligence Black Box & Autonomous Recovery System</p></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><div class="tag" id="connectionBadge">SERVICE · CHECKING</div><div class="tag" id="profileTag">PROFILE · BALANCED</div></div></header>
<section class="grid"><div class="metric"><div class="label">Scenario campaigns</div><div class="value" id="mRuns">—</div><div class="hint">Predefined validation cases across logical device identities</div></div><div class="metric"><div class="label">Verified recoveries</div><div class="value" id="mRecovery">—</div><div class="hint">Healthy-cycle verification passed</div></div><div class="metric"><div class="label">Safe-mode entries</div><div class="value" id="mSafe">—</div><div class="hint">Fault containment engaged</div></div><div class="metric"><div class="label">ML hold-out accuracy</div><div class="value" id="mML">—</div><div class="hint">Synthetic labelled data only</div></div></section>
<section class="panel" id="autonomousPanel"><div class="section-head"><div><h2>Autonomous Operations Session</h2><p class="muted">Start one continuous simulated device session. AIBARS generates normal telemetry, schedules faults internally, diagnoses them, recovers, verifies health and resumes monitoring without selecting individual faults.</p></div><span class="status warn" id="autoStateBadge">SAVED DEMO</span></div><div class="two"><div><label class="muted" for="autoCycles">Healthy monitoring cycles (session limit)</label><input class="search" id="autoCycles" type="number" min="10" max="10000" value="160"><label class="muted" for="autoIncidents" style="display:block;margin-top:8px">Maximum fault episodes</label><input class="search" id="autoIncidents" type="number" min="1" max="20" value="4"><label class="muted" for="autoIntervalMode" style="display:block;margin-top:8px">Fault scheduling mode</label><select class="search" id="autoIntervalMode"><option value="random" selected>Random interval (choose within a range)</option><option value="fixed">Fixed interval (same delay every time)</option></select><div id="autoFixedIntervalGroup" class="hide"><label class="muted" for="autoFixedIntervalSeconds" style="display:block;margin-top:8px">Inject next fault after (seconds)</label><input class="search" id="autoFixedIntervalSeconds" type="number" min="0.4" max="120" step="0.1" value="2.0"></div><div id="autoRandomIntervalGroup"><label class="muted" for="autoMinIntervalSeconds" style="display:block;margin-top:8px">Minimum healthy interval (seconds)</label><input class="search" id="autoMinIntervalSeconds" type="number" min="0.4" max="120" step="0.1" value="2.0"></div></div><div><div id="autoRandomMaxGroup"><label class="muted" for="autoMaxIntervalSeconds">Maximum healthy interval (seconds)</label><input class="search" id="autoMaxIntervalSeconds" type="number" min="0.4" max="120" step="0.1" value="5.0"></div><label class="muted" for="autoSpeed" style="display:block;margin-top:8px">Telemetry update interval (ms)</label><input class="search" id="autoSpeed" type="number" min="20" max="1000" step="10" value="100"><div class="notice">Example: at 100 ms per telemetry cycle, a fixed 2.0-second interval schedules the next episode after 20 healthy monitoring cycles. The simulator then uses five warm-up samples before activating the fault signal. The wait timer pauses during fault diagnosis and recovery.</div><label class="muted" for="autoSeed" style="display:block;margin-top:8px">Random seed (repeatable fault sequence)</label><input class="search" id="autoSeed" type="number" min="0" max="4294967295" value="20261110"></div></div><label style="display:flex;align-items:center;gap:8px;margin-top:12px;color:var(--muted)"><input id="autoCritical" type="checkbox"> Include critical test faults (may intentionally enter safe mode)</label><div class="actions"><button class="btn" id="startAuto">Start autonomous session</button><button class="btn ghost" id="stopAuto" disabled>Stop session</button></div><div class="notice" id="autoNotice">Offline saved-session playback. Start the local dashboard server to run a new autonomous session.</div><div class="grid" style="margin:14px 0 0"><div class="metric"><div class="label">Monitoring cycles</div><div class="value" id="autoCyclesDone">—</div></div><div class="metric"><div class="label">Fault episodes</div><div class="value" id="autoIncidentsDone">—</div></div><div class="metric"><div class="label">Verified recoveries</div><div class="value" id="autoRecoveriesDone">—</div></div><div class="metric"><div class="label">Safe-mode entries</div><div class="value" id="autoSafeDone">—</div></div></div><div class="two"><div class="notice"><b>Current device telemetry</b><div class="kv" id="autoTelemetry" style="margin-top:8px"><div>Temperature</div><div>—</div><div>Voltage</div><div>—</div><div>Current</div><div>—</div><div>Communication</div><div>—</div><div>Primary task</div><div>—</div><div>Secondary task</div><div>—</div></div></div><div class="notice"><b>Current session state</b><div id="autoSessionDetail" style="margin-top:8px">No live session active.</div><div class="bar" style="margin-top:12px"><span id="autoProgress" style="width:0%"></span></div><div style="margin-top:12px;color:var(--muted)">Next fault schedule</div><div id="autoNextFault" style="font-size:21px;font-weight:750;margin-top:3px">Waiting for session</div><div id="autoTimingDetail" class="muted" style="font-size:11px;margin-top:3px">Timing configuration will appear here.</div></div></div><h3 style="font-size:14px;margin:18px 0 8px">Autonomous event stream</h3><ul class="eventlist" id="autoEvents" style="max-height:300px"><li class="muted">Saved autonomous demonstration will appear here.</li></ul><h3 style="font-size:14px;margin:18px 0 8px">Automatically diagnosed incidents</h3><div class="tablewrap"><table><thead><tr><th>Episode</th><th>Fault selected by scheduler</th><th>Diagnosis</th><th>AI advisory</th><th>Risk</th><th>Recovery</th></tr></thead><tbody id="autoEpisodeTable"><tr><td colspan="6" class="muted">No autonomous incident analysis yet.</td></tr></tbody></table></div></section>
<div class="cols"><section class="panel"><h2>Fault Injection Test Bench</h2><p class="muted">This separate bench is for repeatable manual validation. The autonomous session above schedules faults internally and does not require you to select one.</p><div class="scenario-list" id="scenarioList"></div><div class="actions"><button class="btn" id="runLive">Run selected scenario</button><button class="btn ghost" id="resetView">Reset selection</button></div><div class="notice" id="serverNotice">Offline playback mode. Start the local AIBARS dashboard server to launch fresh simulator runs.</div></section>
<section class="panel"><h2>Incident intelligence</h2><div class="two"><div><div class="muted">Risk score</div><div class="risknum" id="riskScore">—</div><span class="status warn" id="riskLevel">NO INCIDENT</span></div><div><div class="muted">ML advisory confidence</div><div class="risknum" id="mlConfidence">—</div><div class="bar"><span id="mlBar" style="width:0%"></span></div></div></div><hr style="border:0;border-top:1px solid var(--line);margin:17px 0"><div class="kv" id="incidentKv"></div><div class="notice" id="riskNote">Select a run to inspect the incident decision.</div></section></div>
<section class="panel"><div class="section-head"><h2>Campaign results</h2><div class="actions" style="margin:0"><button class="btn ghost" id="exportCsv">Export campaign CSV</button><button class="btn ghost" id="exportIncident">Download selected incident JSON</button></div></div><input class="search" id="filter" placeholder="Filter scenarios, diagnoses or status…"><div class="tablewrap"><table><thead><tr><th>Scenario / device</th><th>Detected fault</th><th>Diagnosis</th><th>Risk</th><th>Recovery</th><th>Final state</th></tr></thead><tbody id="resultsBody"></tbody></table></div></section>
<section class="panel"><h2>Risk distribution</h2><p class="muted">Distribution of current campaign risk-triage scores. These are prioritisation bands, not certified safety levels.</p><div id="riskDistribution"></div></section>
<section class="panel"><div class="section-head"><h2>Black-box event timeline <span class="muted" style="font-size:12px;font-weight:400">(pre-fault · fault · recovery · verification)</span></h2><div class="actions" style="margin:0"><button class="btn" id="replayPlay">Play timeline</button><button class="btn ghost" id="replayPause">Pause</button><button class="btn ghost" id="replayNext">Next event</button><button class="btn ghost" id="replayReset">Reset</button></div></div><div class="muted" id="replayPosition" style="font-size:12px;margin:-5px 0 10px">0 / 0 events</div><ul class="eventlist" id="events"></ul></section>
<section class="panel"><h2>Diagnostic explainability</h2><div id="explain" class="muted">Select a scenario to see feature evidence, ML advisory and deterministic recovery rationale.</div></section>
<p class="foot">AIBARS is a laptop-based simulation. Recovery operations act on simulated components only. ML training and hold-out metrics use generated synthetic signatures and are not field accuracy. Risk score is a transparent prioritisation heuristic, not a certified safety assessment.</p>
</main><script>
const DATA=__DATA__;
const AUTONOMOUS_DEMO=__AUTO_DEMO__;
const SCENARIOS=['nominal','sensor_timeout','sensor_stuck','sensor_out_of_range','communication_timeout','task_hang','secondary_task_hang','multiple_task_hangs','multiple_faults','recovery_failure'];
let selected=DATA[0]||null;
let replayIndex=selected?(selected.events||[]).length:0;
let replayTimer=null;
const el=id=>document.getElementById(id);
function fmt(s){return String(s||'').replaceAll('_',' ').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase())}
function esc(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function stateClass(state){return state==='NORMAL'?'good':state==='SAFE_MODE'?'bad':'warn'}
function render(){const fleet=DATA;el('mRuns').textContent=fleet.length;el('mRecovery').textContent=fleet.filter(x=>x.summary.recovery_status==='VERIFIED').length;el('mSafe').textContent=fleet.filter(x=>x.summary.terminal_state==='SAFE_MODE').length;el('mML').textContent=window.ML_ACCURACY||'—';el('scenarioList').innerHTML=SCENARIOS.map(s=>{const r=fleet.find(x=>x.summary.scenario===s);return `<button class="scenario ${selected&&selected.summary.scenario===s?'active':''}" data-s="${esc(s)}"><b>${esc(fmt(s))}</b><small>${r?esc(fmt(r.summary.recovery_status))+' · '+esc(fmt(r.summary.terminal_state)):'No recorded run'}</small></button>`}).join('');document.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>select(b.dataset.s));renderTable();renderRiskDistribution();if(selected)renderSelected();}
function renderRiskDistribution(){const levels=[['LOW','risk-low'],['MODERATE','risk-moderate'],['HIGH','risk-high'],['CRITICAL','risk-critical']];const counts=Object.fromEntries(levels.map(([name])=>[name,DATA.filter(r=>r.risk_assessment.level===name).length]));const maximum=Math.max(1,...Object.values(counts));el('riskDistribution').innerHTML=levels.map(([name,cls])=>`<div class="riskrow"><span>${name}</span><div class="risktrack"><div class="riskfill ${cls}" style="width:${(counts[name]/maximum)*100}%"></div></div><b>${counts[name]}</b></div>`).join('');}
function renderTable(){const q=el('filter').value.toLowerCase();el('resultsBody').innerHTML=DATA.filter(r=>JSON.stringify(r).toLowerCase().includes(q)).map(r=>`<tr><td><b>${esc(fmt(r.summary.scenario))}</b><br><small class="muted">${esc(r.device_id||'SIM-DEVICE')}</small></td><td>${(r.summary.detected_faults||[]).map(x=>esc(fmt(x))).join(', ')||'—'}</td><td>${esc(fmt(r.summary.primary_cause))}</td><td><span class="status ${r.risk_assessment.level==='CRITICAL'||r.risk_assessment.level==='HIGH'?'bad':r.risk_assessment.level==='MODERATE'?'warn':'good'}">${esc(r.risk_assessment.level)} · ${Number(r.risk_assessment.score).toFixed(1)}</span></td><td>${esc(fmt(r.summary.recovery_status))}</td><td><span class="status ${stateClass(r.summary.terminal_state)}">${esc(fmt(r.summary.terminal_state))}</span></td></tr>`).join('');}
function select(s){stopReplay();selected=DATA.find(x=>x.summary.scenario===s)||selected;replayIndex=selected?(selected.events||[]).length:0;render();}
function renderSelected(){const r=selected;if(!r)return;const risk=r.risk_assessment,ml=r.ml_advisory,inc=r.incident||{};el('riskScore').textContent=risk.score;el('riskLevel').textContent=risk.level;el('riskLevel').className='status '+(risk.level==='CRITICAL'||risk.level==='HIGH'?'bad':risk.level==='MODERATE'?'warn':'good');el('mlConfidence').textContent=(ml.confidence*100).toFixed(1)+'%';el('mlBar').style.width=(ml.confidence*100)+'%';el('incidentKv').innerHTML=`<div>Primary diagnosis</div><div><b>${esc(fmt(r.summary.primary_cause))}</b></div><div>Incident severity</div><div>${esc(fmt(inc.severity||'LOW'))}</div><div>Rule match score</div><div>${Number(inc.rule_match_score||0).toFixed(2)}</div><div>Deterministic status</div><div>${esc(fmt(r.summary.recovery_status))}</div><div>Recovery action</div><div>${esc(fmt(r.summary.recovery_action))}</div><div>Attempts / healthy cycles</div><div>${Number(r.summary.recovery_attempts)||0} / ${Number(r.summary.verified_cycles)||0}</div><div>Terminal mode</div><div>${esc(fmt(r.summary.terminal_state))}</div><div>ML advisory</div><div>${esc(fmt(ml.prediction))}</div><div>Configured impact</div><div>${(Number(risk.impact_factor||0)*100).toFixed(0)}%</div>`;el('riskNote').textContent=risk.interpretation;renderTimeline();const evidence=(inc.faults||[]).map(f=>`<li><b>${esc(fmt(f.code))} · ${esc(fmt(f.severity))}</b><div>${esc(f.evidence)}</div></li>`).join('')||'<li>No deterministic fault rule was triggered.</li>';const features=Object.entries(ml.features||{}).map(([k,v])=>`${esc(fmt(k))}: ${Number(v).toFixed(2)}`).join('<br>');const probs=Object.entries(ml.probabilities||{}).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`${esc(fmt(k))} ${(v*100).toFixed(1)}%`).join('<br>')||'Compound-fault rule supersedes single-class model advice.';el('explain').innerHTML=`<div class="two"><div><b>Telemetry-derived feature vector</b><p>${features}</p></div><div><b>ML class scores</b><p>${probs}</p></div></div><hr style="border:0;border-top:1px solid var(--line)"><b>Deterministic rule evidence</b><ul class="evidence-list">${evidence}</ul><b>Model interpretation</b><p>${esc(ml.explanation)}</p><b>Rule-based diagnosis</b><p>${esc(inc.rationale||'No fault rule was triggered.')}</p><b>Recovery result</b><p>${esc(inc.recovery_status||r.summary.recovery_status)}: ${esc(inc.recovery_explanation||'See black-box timeline for the decision trace.')}</p>`;}
function stopReplay(){if(replayTimer!==null){clearInterval(replayTimer);replayTimer=null;}const button=el('replayPlay');if(button)button.textContent='Play timeline';}
function renderTimeline(){const events=selected?.events||[];replayIndex=Math.max(0,Math.min(replayIndex,events.length));el('replayPosition').textContent=`${replayIndex} / ${events.length} events`;el('events').innerHTML=events.slice(0,replayIndex).map(e=>`<li><span class="tick">T+${esc(e.tick)} · #${esc(e.sequence)}</span><br><span class="eventtitle">${esc(e.component)} / ${esc(e.event)}</span><div class="eventdetail">${esc(e.detail)}</div></li>`).join('')||'<li class="muted">Timeline is reset. Play or step forward to inspect events.</li>';el('replayNext').disabled=replayIndex>=events.length;}
el('replayPlay').onclick=()=>{if(replayTimer!==null)return;const count=(selected?.events||[]).length;if(replayIndex>=count)replayIndex=0;renderTimeline();el('replayPlay').textContent='Playing…';replayTimer=setInterval(()=>{replayIndex=Math.min(replayIndex+1,(selected?.events||[]).length);renderTimeline();if(replayIndex>=(selected?.events||[]).length)stopReplay();},350);};
el('replayPause').onclick=stopReplay;
el('replayNext').onclick=()=>{stopReplay();replayIndex=Math.min(replayIndex+1,(selected?.events||[]).length);renderTimeline();};
el('replayReset').onclick=()=>{stopReplay();replayIndex=0;renderTimeline();};
el('filter').addEventListener('input',renderTable);el('resetView').onclick=()=>{el('filter').value='';select('nominal')};
function downloadText(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);}
el('exportCsv').onclick=()=>{const columns=['scenario','device_id','detected_faults','primary_cause','risk_score','risk_level','recovery_status','recovery_attempts','verified_cycles','terminal_state'];const quote=value=>'"'+String(value??'').replaceAll('"','""')+'"';const lines=[columns.join(','),...DATA.map(r=>[r.summary.scenario,r.device_id,(r.summary.detected_faults||[]).join('|'),r.summary.primary_cause,r.risk_assessment.score,r.risk_assessment.level,r.summary.recovery_status,r.summary.recovery_attempts,r.summary.verified_cycles,r.summary.terminal_state].map(quote).join(','))];downloadText('aibars_campaign.csv',lines.join('\r\n'),'text/csv;charset=utf-8');};
el('exportIncident').onclick=()=>{if(!selected){el('serverNotice').textContent='Select a campaign before exporting its incident report.';return;}downloadText('aibars_'+selected.summary.scenario+'_incident.json',JSON.stringify(selected,null,2),'application/json;charset=utf-8');};
el('runLive').onclick=async()=>{const name=selected?.summary.scenario||'sensor_timeout';if(location.protocol==='file:'){el('serverNotice').textContent='Offline playback only. Start python tools/launch_dashboard.py and open http://127.0.0.1:8765 to run live simulations.';return;}el('serverNotice').textContent='Starting '+name+'…';try{const start=await fetch('/api/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:name})});if(!start.ok)throw new Error(await start.text());const meta=await start.json();stopReplay();replayIndex=0;el('serverNotice').textContent='Running '+name+' · '+meta.run_id;let done=false;while(!done){await new Promise(resolve=>setTimeout(resolve,250));const response=await fetch('/api/status?run_id='+encodeURIComponent(meta.run_id));if(!response.ok)throw new Error(await response.text());const state=await response.json();selected={...(selected||{}),events:state.events||[]};replayIndex=(state.events||[]).length;renderTimeline();el('serverNotice').textContent='Running '+name+' · '+state.event_count+' black-box events captured';done=state.done;if(done){if(state.error)throw new Error(state.error);const fresh=state.result;stopReplay();const idx=DATA.findIndex(x=>x.summary.scenario===name);if(idx>=0)DATA[idx]=fresh;else DATA.push(fresh);selected=fresh;replayIndex=(fresh.events||[]).length;render();el('serverNotice').textContent='Simulation completed. Final diagnosis and recovery verification loaded.';}}}catch(err){el('serverNotice').textContent='Run failed: '+err.message;}};
let autonomousSessionId=null,autonomousPolling=false;
function renderAutonomous(status,events,summary,live,analysis){status=status||{};events=events||[];summary=summary||{};analysis=analysis||[];const state=status.session_state||summary.session_state||'SAVED DEMO';el('autoStateBadge').textContent=fmt(state).toUpperCase();el('autoStateBadge').className='status '+(state==='MONITORING'||state==='COMPLETED'?'good':state==='SAFE_MODE'?'bad':'warn');el('autoCyclesDone').textContent=status.session_cycles??summary.session_cycles??'—';el('autoIncidentsDone').textContent=status.incidents??summary.incidents??'—';el('autoRecoveriesDone').textContent=status.verified_recoveries??summary.verified_recoveries??'—';el('autoSafeDone').textContent=status.safe_mode_entries??summary.safe_mode_entries??'—';const temp=status.temperature_c,volt=status.voltage_v,current=status.current_a;el('autoTelemetry').innerHTML=`<div>Temperature</div><div>${temp===undefined?'—':Number(temp).toFixed(2)+' °C'}</div><div>Voltage</div><div>${volt===undefined?'—':Number(volt).toFixed(2)+' V'}</div><div>Current</div><div>${current===undefined?'—':Number(current).toFixed(2)+' A'}</div><div>Communication</div><div>${status.communication_ok===undefined?'—':status.communication_ok?'Healthy':'Lost'}</div><div>Primary task</div><div>${status.primary_task_progressing===undefined?'—':status.primary_task_progressing?'Progressing':'Stalled'}</div><div>Secondary task</div><div>${status.secondary_task_progressing===undefined?'—':status.secondary_task_progressing?'Progressing':'Stalled'}</div>`;const max=Number(status.maximum_cycles||summary.session_cycles||1);const done=Number(status.session_cycles||summary.session_cycles||0);const terminal=['COMPLETED','SAFE_MODE','STOPPED'].includes(state);el('autoProgress').style.width=(terminal?100:Math.min(100,100*done/max))+'%';el('autoSessionDetail').textContent=`Device: ${status.device_id||summary.device_id||'AIBARS-AUTO-ECU-01'} · Scenario: ${fmt(status.current_scenario||'nominal')} · Global tick: ${status.global_tick??summary.global_ticks??'—'} · Seed: ${status.seed??summary.seed??'—'}`;const mode=status.interval_mode||summary.interval_mode||'RANDOM';const minSec=status.fault_interval_min_seconds??summary.fault_interval_min_seconds;const maxSec=status.fault_interval_max_seconds??summary.fault_interval_max_seconds;const eta=status.next_fault_in_seconds;if(state==='MONITORING'&&eta!==undefined){el('autoNextFault').textContent=Number(eta).toFixed(1)+' s';}else if(state==='FAULT_INJECTED'||state==='MONITORING_FAULT_EPISODE'||state==='DIAGNOSING'||state==='RECOVERING_AND_VERIFYING'){el('autoNextFault').textContent='Current fault episode in progress';}else if(terminal){el('autoNextFault').textContent='Session ended';}else{el('autoNextFault').textContent='Waiting for session';}el('autoTimingDetail').textContent=`${mode==='FIXED'?'Fixed':'Random'} healthy-monitoring interval · ${minSec===undefined?'—':Number(minSec).toFixed(1)+' s'}${mode==='FIXED'?'':' to '+(maxSec===undefined?'—':Number(maxSec).toFixed(1)+' s')} · telemetry tick ${status.tick_delay_ms??'—'} ms`;el('autoEvents').innerHTML=events.slice(-100).reverse().map(e=>`<li><span class="tick">T+${esc(e.tick)} · #${esc(e.sequence)}</span><br><span class="eventtitle">${esc(e.component)} / ${esc(e.event)}</span><div class="eventdetail">${esc(e.detail)}</div></li>`).join('')||'<li class="muted">No autonomous events recorded yet.</li>';el('autoEpisodeTable').innerHTML=analysis.map(item=>{const ep=item.episode||{},risk=item.risk_assessment||{},ml=item.ml_advisory||{};return `<tr><td>${esc(ep.episode)}</td><td>${esc(fmt(ep.scenario))}</td><td>${esc(fmt(ep.primary_cause))}</td><td>${esc(fmt(ml.prediction))} · ${(Number(ml.confidence||0)*100).toFixed(1)}%</td><td><span class="status ${risk.level==='CRITICAL'||risk.level==='HIGH'?'bad':risk.level==='MODERATE'?'warn':'good'}">${esc(risk.level||'—')} ${risk.score===undefined?'':'· '+Number(risk.score).toFixed(1)}</span></td><td>${esc(fmt(ep.recovery_status||'—'))}</td></tr>`}).join('')||'<tr><td colspan="6" class="muted">Episode AI/risk analysis is loaded after the autonomous session completes.</td></tr>';el('startAuto').disabled=Boolean(live);el('stopAuto').disabled=!live;}
function showSavedAutonomousDemo(){if(AUTONOMOUS_DEMO&&AUTONOMOUS_DEMO.status){renderAutonomous(AUTONOMOUS_DEMO.status,AUTONOMOUS_DEMO.events||[],AUTONOMOUS_DEMO.summary||{},false,AUTONOMOUS_DEMO.episode_analysis||[]);el('autoNotice').textContent='Saved autonomous session preview. Start the local dashboard server to run a new session with automatic fault scheduling.';}}
async function pollAutonomous(){if(!autonomousSessionId||autonomousPolling)return;autonomousPolling=true;try{let done=false;while(!done&&autonomousSessionId){await new Promise(resolve=>setTimeout(resolve,250));const response=await fetch('/api/autonomous/status?session_id='+encodeURIComponent(autonomousSessionId),{cache:'no-store'});if(!response.ok)throw new Error(await response.text());const result=await response.json();renderAutonomous(result.status,result.events,result.summary,!result.done,result.episode_analysis||[]);el('autoNotice').textContent=`Autonomous session ${result.done?'finished':'running'} · ${result.event_count} events captured`+(result.error?' · '+result.error:'');done=result.done;if(done){if(result.error)throw new Error(result.error);el('autoNotice').textContent=`Session ${fmt(result.status.session_state||result.summary.session_state)} · ${result.summary.incidents??0} incidents · ${result.summary.verified_recoveries??0} verified recoveries. Full event history saved in runs/autonomous.`;}}}catch(err){el('autoNotice').textContent='Autonomous session error: '+err.message;}finally{autonomousPolling=false;autonomousSessionId=null;el('startAuto').disabled=false;el('stopAuto').disabled=true;}}
function updateIntervalModeControls(){const fixed=el('autoIntervalMode').value==='fixed';el('autoFixedIntervalGroup').classList.toggle('hide',!fixed);el('autoRandomIntervalGroup').classList.toggle('hide',fixed);el('autoRandomMaxGroup').classList.toggle('hide',fixed);}
el('autoIntervalMode').addEventListener('change',updateIntervalModeControls);updateIntervalModeControls();
el('startAuto').onclick=async()=>{if(location.protocol==='file:'){el('autoNotice').textContent='Offline playback only. Start RUN_AIBARS_WINDOWS.bat or run python tools/launch_dashboard.py, then open http://127.0.0.1:8765.';return;}const value=id=>Number(el(id).value);const mode=el('autoIntervalMode').value;const config={session_cycles:value('autoCycles'),max_incidents:value('autoIncidents'),interval_mode:mode,tick_delay_ms:value('autoSpeed'),seed:value('autoSeed'),critical_fault_percent:el('autoCritical').checked?10:0};if(mode==='fixed'){config.interval_seconds=value('autoFixedIntervalSeconds');}else{config.interval_min_seconds=value('autoMinIntervalSeconds');config.interval_max_seconds=value('autoMaxIntervalSeconds');if(config.interval_max_seconds<config.interval_min_seconds){el('autoNotice').textContent='Maximum interval must be greater than or equal to minimum interval.';return;}}el('startAuto').disabled=true;el('autoNotice').textContent='Starting autonomous supervisor…';try{const response=await fetch('/api/autonomous/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(config)});if(!response.ok)throw new Error(await response.text());const result=await response.json();autonomousSessionId=result.session_id;const timing=result.config||{};el('autoNotice').textContent=`Session started · ${timing.interval_mode||mode} scheduling · effective interval ${Number(timing.effective_min_seconds||0).toFixed(1)}${timing.interval_mode==='fixed'?'':'–'+Number(timing.effective_max_seconds||0).toFixed(1)} seconds of healthy monitoring after each recovery.`;await pollAutonomous();}catch(err){el('autoNotice').textContent='Unable to start: '+err.message;el('startAuto').disabled=false;}};
el('stopAuto').onclick=async()=>{if(!autonomousSessionId)return;el('autoNotice').textContent='Stop requested. AIBARS will finish the current recovery boundary safely.';try{const response=await fetch('/api/autonomous/stop',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:autonomousSessionId})});if(!response.ok)throw new Error(await response.text());}catch(err){el('autoNotice').textContent='Stop request failed: '+err.message;}};
async function checkServer(){if(location.protocol==='file:'){el('connectionBadge').textContent='SERVICE · OFFLINE PLAYBACK';showSavedAutonomousDemo();return;}try{const response=await fetch('/api/health',{cache:'no-store'});if(!response.ok)throw new Error('unavailable');const health=await response.json();el('connectionBadge').textContent=health.status==='ok'?'SERVICE · LIVE':'SERVICE · UNAVAILABLE';if(health.profile_name)el('profileTag').textContent='PROFILE · '+health.profile_name;}catch(_){el('connectionBadge').textContent='SERVICE · UNAVAILABLE';}}
window.ML_ACCURACY=__ACC__;
el('profileTag').textContent='PROFILE · '+__PROFILE__;render();if(DATA.some(x=>x.summary.scenario==='nominal'))select('nominal');checkServer();
</script></body></html>'''
    safe_profile = json.dumps(str(profile_name)).replace("</", "<\\/")
    page = page.replace("__DATA__", safe_json).replace("__AUTO_DEMO__", safe_auto).replace("__ACC__", json.dumps(_ml_accuracy(records)))
    page = page.replace("__PROFILE__", safe_profile)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(page, encoding="utf-8")


def _ml_accuracy(records: list[dict]) -> str:
    # The metric is read from the generated held-out evaluation report, not guessed.
    project_root = pathlib.Path(__file__).resolve().parents[1]
    report_path = project_root / "artifacts" / "ml_evaluation.json"
    if report_path.is_file():
        report = json.loads(report_path.read_text(encoding="utf-8"))
        return f"{report.get('accuracy', 0.0) * 100:.1f}% (synthetic)"
    return "Not evaluated"
